"""Read-only issued approval projections generated by actual isolated SQL."""
from copy import deepcopy
from datetime import datetime,timezone
from urllib.parse import urlparse,parse_qs
import re

def response(path,method,body,headers,state):
    w=state.get('contract_approval_workspace');token=(headers.get('Authorization')or headers.get('authorization','')).removeprefix('Bearer ');route=urlparse(path).path;q={k:v[0]for k,v in parse_qs(urlparse(path).query).items()}
    if not w or token not in state['sessions']:return None
    admin=token in state['accounts_workspace']['admin_tokens']
    if route=='/api/mobile/v1/catalogue/contracts'and method=='GET'and q.get('search')in('9205','9206'):
        rows=[deepcopy(row)for row in w['records']if str(row['id'])==q['search']]
        return 200,{'rows':rows,'total':len(rows),'page':1,'pages':1,'statusCounts':[],'updatedAt':datetime.now(timezone.utc).isoformat()},False
    for row in w['records']:
        if route==f"/api/mobile/v1/catalogue/contracts/{row['id']}"and method=='GET':return 200,deepcopy(row),False
    matched=re.fullmatch(r'/api/mobile/v1/contracts/([1-9]\d*)/approval',route)
    if matched and method=='GET':
        index=int(matched[1]);context=deepcopy(w['unapproved']if admin else w['readonly'])if index==9205 else deepcopy(w['approved'])if index==9206 else {'id':index,'approval':None}
        return 200,context,False
    if matched and method!='GET':return 400,{'message':'Portfolio duyệt sở hữu chỉ kiểm màn hình. Actual web writer, UUID và lịch sử đã kiểm bằng SQL nhúng.','code':'QA_APPROVAL_READ_ONLY'},False
    return None
